        items = []
        offset_buckets = lag * minutes * 60
        for bucket in sorted(bucket_means):
            previous = bucket_means.get(bucket - offset_buckets)
            if previous is None:
                continue
            current = bucket_means[bucket]
            paired: list[Decimal] = []
            for endpoint_a, endpoint_b in sorted(edges):
                if (
